// deviceKeyWhereR holds the relationship-based filters of
// deviceKeyWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type deviceKeyWhereR[Q psql.Filterable] struct {
	cols deviceKeyColumns
}

// HasSharedKey filters parents that have a matching SharedKey using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to SharedKeys).
func (w deviceKeyWhereR[Q]) HasSharedKey(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := psql.Select(
		sm.Columns(psql.Raw("1")),
		sm.From(SharedKeys.NameExpr()),
		sm.Where(SharedKeys.Columns.ID.EQ(w.cols.SharedKeyID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: psql.Exists(q)}
}

func (o *DeviceKey) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "SharedKey":
		rel, ok := retrieved.(*SharedKey)
		if !ok {
			return fmt.Errorf("deviceKey cannot load %T as %q", retrieved, name)
		}

		o.R.SharedKey = rel
		o.R.Loaded.SharedKey = true

		if rel != nil {
			rel.R.DeviceKeys = DeviceKeySlice{o}
		}
		return nil
	default:
		return fmt.Errorf("deviceKey has no relationship %q", name)
	}
}

type deviceKeyPreloader struct {
	SharedKey func(...psql.PreloadOption) psql.Preloader
}

func buildDeviceKeyPreloader() deviceKeyPreloader {
	return deviceKeyPreloader{
		SharedKey: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*SharedKey, SharedKeySlice](psql.PreloadRel{
				Name: "SharedKey",
				Sides: []psql.PreloadSide{
					{
						From:        DeviceKeys,
						To:          SharedKeys,
						FromColumns: []string{"shared_key_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, SharedKeys.Columns.Names(), sharedKeyScanMapperNullable, opts...)
		},
	}
}

