// LoadSharedKey loads the deviceKey's SharedKey into the .R struct
func (o *DeviceKey) LoadSharedKey(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.SharedKey = nil
	o.R.Loaded.SharedKey = false

	related, err := o.SharedKey(mods...).One(ctx, exec)
	if err != nil {
		return err
	}

	related.R.DeviceKeys = DeviceKeySlice{o}

	o.R.SharedKey = related
	o.R.Loaded.SharedKey = true
	return nil
}

// LoadSharedKey loads the deviceKey's SharedKey into the .R struct
func (os DeviceKeySlice) LoadSharedKey(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	sharedKeys, err := os.SharedKey(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.SharedKey = nil
		o.R.Loaded.SharedKey = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	deviceKeyByKey := make(map[uuid.UUID][]*DeviceKey, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		deviceKeyByKey[o.SharedKeyID] = append(deviceKeyByKey[o.SharedKeyID], o)
	}

	for _, rel := range sharedKeys {

		owners, ok := deviceKeyByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.SharedKey != nil {
				continue
			}

			rel.R.DeviceKeys = append(rel.R.DeviceKeys, o)

			o.R.SharedKey = rel

		}
	}

	return nil
}

type deviceKeyJoins[Q dialect.Joinable] struct {
	typ       string
	SharedKey modAs[Q, sharedKeyColumns]
}

func (j deviceKeyJoins[Q]) aliasedAs(alias string) deviceKeyJoins[Q] {
	return buildDeviceKeyJoins[Q](buildDeviceKeyColumns(alias), j.typ)
}

func buildDeviceKeyJoins[Q dialect.Joinable](cols deviceKeyColumns, typ string) deviceKeyJoins[Q] {
	return deviceKeyJoins[Q]{
		typ: typ,
		SharedKey: modAs[Q, sharedKeyColumns]{
			c: SharedKeys.Columns,
			f: func(to sharedKeyColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SharedKeys.NameExpr().As(to.Alias())).On(
						to.ID.EQ(cols.SharedKeyID),
					))
				}

				return mods
			},
		},
	}
}
